package oracle;
import java.util.*;import java.io.*;import org.json.simple.*;import org.json.simple.parser.*;import core.game.world.map.*;import core.game.node.entity.*;import core.game.node.entity.player.Player;import core.game.node.entity.npc.NPC;
public class Support {
 public static Map<String,Object>input;public static TreeMap<Integer,Entity>nodes;public static TreeMap<String,RegionChunk>chunks;public static TreeMap<Integer,Region>regions;public static List<Object>events;public static Map<String,Integer>calls;static Set<Integer>hooks;static int clock;
 public static int num(Object x){return ((Number)x).intValue();}public static Object get(Map m,String k,Object d){return m.containsKey(k)?m.get(k):d;}
 public static Location loc(Object x){if(x==null)return null;List a=(List)x;return new Location(num(a.get(0)),num(a.get(1)),num(a.get(2)));}public static List<Integer>coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}public static String key(Location l){return(l.getX()>>3)+","+(l.getY()>>3)+","+l.getZ();}public static int rid(Location l){return((l.getX()>>6)<<8)|(l.getY()>>6);}
 public static class Failure extends RuntimeException{}
 public static void emit(String event,Object...args){ArrayList<Object>a=new ArrayList<>();a.add(event);a.addAll(Arrays.asList(args));events.add(a);int n=calls.merge(event,1,Integer::sum);List hs=(List)get(input,"hooks",Collections.emptyList());for(int i=0;i<hs.size();i++){Map h=(Map)hs.get(i);if(event.equals(h.get("event"))&&n==num(get(h,"at",1))&&hooks.add(i))for(Object op:(List)h.get("actions"))act((Map)op);}Map f=(Map)get(input,"failures",Collections.emptyMap());if(f.containsKey(event)&&num(f.get(event))==n)throw new Failure();}
 static Region rawRegion(Location l){return regions.computeIfAbsent(rid(l),i->new Region(i));}static RegionChunk rawChunk(Location l){return chunks.computeIfAbsent(key(l),s->new RegionChunk(new Location((l.getX()>>3)<<3,(l.getY()>>3)<<3,l.getZ())));}
 public static Region region(Location l){Region r=rawRegion(l);emit("region",coord(l));return r;}public static RegionChunk chunk(Location l){RegionChunk c=rawChunk(l);emit("chunk",coord(l));return c;}
 public static long now(){List a=(List)get(input,"clock",Arrays.asList(1000L));long n=((Number)a.get(Math.min(clock++,a.size()-1))).longValue();emit("clock",n);return n;}
 public static List<Integer>ids(List a){List<Integer>r=new ArrayList<>();for(Object x:a)r.add(x==null?null:((Entity)x).slot);return r;}
 public static Object act(Map a){String op=(String)a.get("op");Entity n=a.get("node")==null?null:nodes.get(num(a.get("node")));switch(op){
 case"move":RegionManager.move(n,loc(a.get("src")),loc(a.get("dst")));return null;
 case"query":Location l=loc(a.get("location"));int d=num(a.get("distance"));String s=(String)get(a,"select","all");return ids(s.equals("players")?RegionManager.players(l,d):s.equals("npcs")?RegionManager.npcs(l,d):RegionManager.all(l,d));
 case"add":case"remove":RegionChunk c=rawChunk(loc(a.get("chunk")));boolean p="players".equals(a.get("list"));if(Boolean.TRUE.equals(a.get("raw"))){List list=p?c.players:c.npcs;if(op.equals("add"))list.add(n);else list.remove(n);}else if(p){if(op.equals("add"))c.addPlayer((Player)n);else c.removePlayer((Player)n);}else{if(op.equals("add"))c.add((NPC)n);else c.remove((NPC)n);}return null;
 case"clear":c=rawChunk(loc(a.get("chunk")));(a.get("list").equals("players")?c.players:c.npcs).clear();return null;
 case"set":if(a.containsKey("location"))n.rawLocation(loc(a.get("location")));if(a.containsKey("footprint"))n.walkingQueue.rawFootprint(loc(a.get("footprint")));if(a.containsKey("name"))n.rawName((String)a.get("name"));return null;
 case"rebase":rawChunk(loc(a.get("chunk"))).currentBase=loc(a.get("base"));return null;
 case"tolerance":rawRegion(loc(a.get("region"))).tolerances.put((String)a.get("name"),a.get("value")==null?null:((Number)a.get("value")).longValue());return null;
 case"tolerated":return rawRegion(loc(a.get("region"))).isTolerated((Player)n);
 default:throw new IllegalArgumentException(op);}}
 public static Object evaluate(Map data){input=data;nodes=new TreeMap<>();chunks=new TreeMap<>();regions=new TreeMap<>();events=new ArrayList<>();calls=new HashMap<>();hooks=new HashSet<>();clock=0;for(Object value:(List)get(data,"nodes",Collections.emptyList())){Map a=(Map)value;int id=num(a.get("id"));String kind=(String)get(a,"kind","npc");Entity n=kind.equals("player")?new Player(id):kind.equals("npc")?new NPC(id):new Entity(id);n.rawLocation(loc(a.get("location")));n.rawName((String)get(a,"name","p"+id));n.walkingQueue.rawFootprint(loc(get(a,"footprint",a.get("location"))));nodes.put(id,n);}List<Object>results=new ArrayList<>();for(Object op:(List)data.get("actions")){try{Map r=new LinkedHashMap();r.put("value",act((Map)op));results.add(r);}catch(Throwable e){while(e.getCause()!=null)e=e.getCause();String err=e instanceof Failure?"Failure":e instanceof NullPointerException?"Null":e instanceof ConcurrentModificationException?"ConcurrentModification":e.getClass().getSimpleName();results.add(Collections.singletonMap("error",err));}}
 Map out=new LinkedHashMap();out.put("results",results);out.put("events",events);Map cs=new TreeMap();for(Map.Entry<String,RegionChunk>e:chunks.entrySet()){Map r=new LinkedHashMap();r.put("players",ids(e.getValue().players));r.put("npcs",ids(e.getValue().npcs));r.put("base",coord(e.getValue().currentBase));cs.put(e.getKey(),r);}out.put("chunks",cs);Map rs=new TreeMap();for(Map.Entry<Integer,Region>e:regions.entrySet())rs.put(e.getKey().toString(),new TreeMap(e.getValue().tolerances));out.put("regions",rs);Map ns=new TreeMap();for(Entity n:nodes.values()){Map r=new LinkedHashMap();r.put("location",coord(n.rawLocation()));r.put("name",n.rawName());r.put("footprint",coord(n.walkingQueue.rawFootprint()));ns.put(""+n.slot,r);}out.put("nodes",ns);return out;}
 public static void main(String[]args)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(System.in,"UTF-8"));String l;JSONParser p=new JSONParser();while((l=r.readLine())!=null){Map data=(Map)p.parse(l);Object out=evaluate(data);Map result=new LinkedHashMap(data);result.put("expected",out);System.out.println(JSONValue.toJSONString(result));}}
}
